parameters.jsCode:
// This code runs once and combines all incoming items into one output

const items = $input.all();

let weekGoneBy = '';
let gainers = '';
let losers = '';
let unlisted = '';
let weekAhead = '';

for (const item of items) {
  const type = item.json.type;
  const content = item.json.content || '';

  if (type === 'week_gone_by') {
    weekGoneBy = content;
  } else if (type === 'gainers') {
    gainers = content;
  } else if (type === 'losers') {
    losers = content;
  } else if (type === 'unlisted') {
    unlisted = content;
  } else if (type === 'week_ahead') {
    weekAhead = content;
  }
}

const combined = 
`WeekGoneBy:
${weekGoneBy}

Gainers:
${gainers}

Losers:
${losers}

UnlistedEquity:
${unlisted}

WeekAhead:
${weekAhead}`;

return [
  {
    json: {
      weekGoneBy,
      gainers,
      losers,
      unlisted,
      weekAhead,
      combined,
    },
  },
];
